function BusinessSnapshot{
 $groups=[ordered]@{};foreach($name in @($raw.groups.Keys|Sort-Object)){if($name-cnotmatch '^(dbo|erp_migration)\.[a-zA-Z0-9_]+$'){throw 'BUSINESS_READY_PERFORMANCE_SNAPSHOT_TABLE'};$parts=$name.Split('.');$qualified='['+$parts[0]+'].['+$parts[1]+']';$cmd=$cn.CreateCommand();$cmd.Transaction=$tx;$cmd.CommandTimeout=900;$cmd.CommandText="SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT x.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2) rowHash FROM $qualified x ORDER BY rowHash";$r=$cmd.ExecuteReader();$digest=[Security.Cryptography.IncrementalHash]::CreateHash([Security.Cryptography.HashAlgorithmName]::SHA256);$count=0L;try{$digest.AppendData([Text.Encoding]::UTF8.GetBytes('['));while($r.Read()){$h=$r.GetString(0);if($h-cnotmatch '^[A-F0-9]{64}$'){throw 'BUSINESS_READY_PERFORMANCE_ROW_HASH'};$prefix=if($count-eq 0){'"'}else{',"'};$digest.AppendData([Text.Encoding]::UTF8.GetBytes($prefix+$h+'"'));$count++};$digest.AppendData([Text.Encoding]::UTF8.GetBytes(']'));$groups[$name]=[ordered]@{count=$count;hash=[Convert]::ToHexString($digest.GetHashAndReset())}}finally{$r.Close();$cmd.Dispose();$digest.Dispose()}};return $groups
